class Solution:
    def reverseWordsWithSameVowelCount(self, s: str) -> str:
        vowels = set('aeiou')
        def cnt(w):
            return sum(c in vowels for c in w)
        words = s.split()
        k = cnt(words[0])
        res = [words[0]]
        for w in words[1:]:
            res.append(w[::-1] if cnt(w) == k else w)
        return ' '.join(res)

