class Solution {
public:
    string reverseWordsWithSameVowelCount(string s) {
        auto cnt = [](const string& w) {
            int c = 0;
            for (char ch : w) if (string("aeiou").find(ch) != string::npos) c++;
            return c;
        };
        vector<string> words;
        string cur;
        stringstream ss(s);
        while (ss >> cur) words.push_back(cur);
        int k = cnt(words[0]);
        string res = words[0];
        for (size_t i = 1; i < words.size(); i++) {
            res += ' ';
            if (cnt(words[i]) == k) reverse(words[i].begin(), words[i].end());
            res += words[i];
        }
        return res;
    }
};

