class Solution {
    public String reverseWordsWithSameVowelCount(String s) {
        String[] words = s.split(" ");
        int k = count(words[0]);
        StringBuilder sb = new StringBuilder(words[0]);
        for (int i = 1; i < words.length; i++) {
            sb.append(' ');
            sb.append(count(words[i]) == k ? new StringBuilder(words[i]).reverse().toString() : words[i]);
        }
        return sb.toString();
    }
    private int count(String w) {
        int c = 0;
        for (char ch : w.toCharArray()) if ("aeiou".indexOf(ch) >= 0) c++;
        return c;
    }
}

