        def cnt(seg):
            return sum(c in vs for c in seg)
        n = len(s)
        res = []
        target = -1
        i = 0
        while i < n:
            j = i
            while j < n and s[j] != ' ':
                j += 1
            if target < 0:
                target = cnt(s[i:j])
                res.append(s[i:j])
            elif cnt(s[i:j]) == target:
                res.append(s[j-1:i-1:-1] if i > 0 else s[:j][::-1])
            else:
                res.append(s[i:j])
            i = j + 1
        return ' '.join(res)

