public:
    string reverseWordsWithSameVowelCount(string s) {
        auto isV = [](char c) { return string("aeiou").find(c) != string::npos; };
        string res;
        int target = -1;
        int i = 0, n = s.size();
        bool first = true;
        while (i < n) {
            int j = i;
            while (j < n && s[j] != ' ') j++;
            int c = 0;
            for (int t = i; t < j; t++) if (isV(s[t])) c++;
            if (!first) res += ' ';
            if (target < 0) { target = c; for (int t = i; t < j; t++) res += s[t]; }
            else if (c == target) { for (int t = j - 1; t >= i; t--) res += s[t]; }
            else { for (int t = i; t < j; t++) res += s[t]; }
            first = false;
            i = j + 1;
        }
        return res;
    }
};

