class Solution {
    public String reverseWordsWithSameVowelCount(String s) {
        StringBuilder res = new StringBuilder();
        int target = -1, i = 0, n = s.length();
        boolean first = true;
        while (i < n) {
            int j = i;
            while (j < n && s.charAt(j) != ' ') j++;
            int c = 0;
            for (int t = i; t < j; t++) if ("aeiou".indexOf(s.charAt(t)) >= 0) c++;
            if (!first) res.append(' ');
            if (target < 0) { target = c; res.append(s, i, j); }
            else if (c == target) { for (int t = j - 1; t >= i; t--) res.append(s.charAt(t)); }
            else res.append(s, i, j);
            first = false;
            i = j + 1;
        }
        return res.toString();
    }
}

